		/// <inheritdoc cref="ProcessTraceAddBufferToBufferStream(winmdroot.System.Diagnostics.Etw.PROCESSTRACE_HANDLE, winmdroot.System.Diagnostics.Etw.ETW_BUFFER_HEADER*, uint)"/>
		public static unsafe uint ProcessTraceAddBufferToBufferStream(winmdroot.System.Diagnostics.Etw.PROCESSTRACE_HANDLE TraceHandle, ReadOnlySpan<byte> Buffer)
