		[SupportedOSPlatform("windows8.0")]
		public static unsafe uint EventSetInformation(winmdroot.System.Diagnostics.Etw.REGHANDLE RegHandle, winmdroot.System.Diagnostics.Etw.EVENT_INFO_CLASS InformationClass, ReadOnlySpan<byte> EventInformation)
		{
