			{
				uint __result = PInvoke.EventSetInformation(RegHandle, InformationClass, (void* )EventInformationLocal, (uint )EventInformation.Length);
				return __result;
			}
		}

		/// <summary>Configures an ETW event provider.</summary>
		/// <param name="RegHandle">
		/// <para>Event provider registration handle. This is a handle returned by [EventRegister](/windows/desktop/api/evntprov/nf-evntprov-eventregister).</para>
		/// <para><see href="https://learn.microsoft.com/windows/win32/api/evntprov/nf-evntprov-eventsetinformation#parameters">Read more on learn.microsoft.com</see>.</para>
		/// </param>
