		public static extern unsafe uint EventSetInformation(winmdroot.System.Diagnostics.Etw.REGHANDLE RegHandle, winmdroot.System.Diagnostics.Etw.EVENT_INFO_CLASS InformationClass, void* EventInformation, uint InformationLength);

