			Marshal.SetLastPInvokeError(Marshal.GetLastSystemError());
			return __retVal;

			[DllImport("ADVAPI32.dll", ExactSpelling = true, EntryPoint = "CreateProcessWithLogonW"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)]
			static extern unsafe winmdroot.Foundation.BOOL LocalExternFunction(winmdroot.Foundation.PCWSTR lpUsername, [Optional] winmdroot.Foundation.PCWSTR lpDomain, winmdroot.Foundation.PCWSTR lpPassword, winmdroot.System.Threading.CREATE_PROCESS_LOGON_FLAGS dwLogonFlags, [Optional] winmdroot.Foundation.PCWSTR lpApplicationName, [Optional] winmdroot.Foundation.PWSTR lpCommandLine, winmdroot.System.Threading.PROCESS_CREATION_FLAGS dwCreationFlags, [Optional] void* lpEnvironment, [Optional] winmdroot.Foundation.PCWSTR lpCurrentDirectory, winmdroot.System.Threading.STARTUPINFOW* lpStartupInfo, winmdroot.System.Threading.PROCESS_INFORMATION* lpProcessInformation);
		}

