		/// </remarks>
		[SupportedOSPlatform("windows8.1")]
		public static unsafe int recvfrom(winmdroot.Networking.WinSock.SOCKET s, winmdroot.Foundation.PSTR buf, int len, int flags, [Optional] winmdroot.Networking.WinSock.SOCKADDR* from, [Optional] int* fromlen)
