			Marshal.SetLastPInvokeError(Marshal.GetLastSystemError());
			return __retVal;

			[DllImport("WS2_32.dll", ExactSpelling = true, EntryPoint = "setsockopt"),DefaultDllImportSearchPaths(DllImportSearchPath.System32)]
			static extern int LocalExternFunction(winmdroot.Networking.WinSock.SOCKET s, int level, int optname, [Optional] winmdroot.Foundation.PCSTR optval, int optlen);
		}

		/// <summary>The shutdown function (winsock.h) disables sends or receives on a socket.</summary>
		/// <param name="s">A descriptor identifying a socket.</param>
		/// <param name="how">
		/// <para>A flag that describes what types of operation will no longer be allowed. Possible values for this flag are listed in the <i>Winsock2.h</i> header file. </para>
		/// <para>This doc was truncated.</para>
