		/// <para><see href="https://learn.microsoft.com/windows/win32/api/iphlpapi/nf-iphlpapi-getnetworkparams#">Read more on learn.microsoft.com</see>.</para>
		/// </remarks>
		[DllImport("IPHLPAPI.dll", ExactSpelling = true),DefaultDllImportSearchPaths(DllImportSearchPath.System32)]
		[SupportedOSPlatform("windows5.0")]
		public static extern unsafe winmdroot.Foundation.WIN32_ERROR GetNetworkParams([Optional] winmdroot.NetworkManagement.IpHelper.FIXED_INFO_W2KSP1* pFixedInfo, uint* pOutBufLen);

